<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { api } from '../api'
import type { ChoiceOption, Page, Product } from '../types'
import { useEvents } from '../events'
import ItemCard from '../components/ItemCard.vue'
import ItemCreateDialog from '../components/ItemCreateDialog.vue'
import { itemPath } from '../utils'
const router = useRouter(); const route = useRoute(); const items = ref<Product[]>([]); const query = ref(''); const category = ref(''); const source = ref(''); const status = ref(''); const categories = ref<string[]>([]); const statuses = ref<ChoiceOption[]>([]); const creating = ref(false); const error = ref(''); const busy = ref(false); const total = ref(0); let requestID = 0

async function load(more = false) { const request = ++requestID; busy.value = true; error.value = ''; try { const p = new URLSearchParams({ q: query.value, use_category: category.value, limit: '100', offset: String(more ? items.value.length : 0) }); if (typeof route.query.company_id === 'string') p.set('company_id',route.query.company_id); if (status.value) p.set('status',status.value); if (source.value) p.set('source',source.value); const result = await api<Page<Product>>(`/tools?${p}`); if (request !== requestID) return; items.value = more ? [...items.value,...result.items] : result.items; total.value = result.total } catch (e) { if (request === requestID) error.value = (e as Error).message } finally { if (request === requestID) busy.value = false } }
function created(item: Product) { creating.value = false; void router.push(itemPath(item)) }
async function loadChoices() { try { const [uses,states] = await Promise.all([api<{items:string[]}>('/tool-categories'),api<{items:ChoiceOption[]}>('/product-options/statuses')]);categories.value=uses.items;statuses.value=states.items } catch(e){error.value=(e as Error).message} }
watch(() => route.query.company_id, () => void load()); watch([query,category,status,source], () => void load()); onMounted(() => { void load(); void loadChoices() }); useEvents(() => { void load(); void loadChoices() })
</script>
<template><section><div class="page-heading"><div><h1>道具库</h1><p>记录道具的获得途径、触发方式与使用效果。</p></div><button class="primary" @click="creating = true">创建道具</button></div><p v-if="route.query.company_id" class="muted">正在查看所选公司旗下道具 · <RouterLink to="/tools">查看全部公司</RouterLink></p><form class="toolbar" @submit.prevent="load()"><input v-model="query" type="search" aria-label="搜索道具" placeholder="搜索名称、效果、公司或获取来源" /><select v-model="category" aria-label="按使用类别筛选"><option value="">全部使用类别</option><option v-for="item in categories" :key="item">{{ item }}</option></select><select v-model="source" aria-label="按来源筛选"><option value="">全部获取来源</option><option v-for="method in ['购买','NPC 赠送','任务奖励','事件奖励','成就解锁','合成获得','初始持有','其他']" :key="method">{{ method }}</option></select><select v-model="status" aria-label="按制作状态筛选"><option value="">全部制作状态</option><option v-for="option in statuses" :key="option.value" :value="option.value">{{ option.label }}</option></select></form><p v-if="error" class="error-text">{{ error }} <button class="button-link" @click="load()">重试</button></p><p v-if="busy && !items.length" class="muted">读取中…</p><div v-else-if="items.length" class="product-grid"><ItemCard v-for="item in items" :key="item.id" :item="item" /></div><div v-else class="empty-state">{{ query || category || source || status ? '没有符合条件的道具。' : '还没有道具，先记录一个名称或效果吧。' }}</div><button v-if="items.length < total" class="secondary load-more" :disabled="busy" @click="load(true)">加载更多</button></section><ItemCreateDialog v-if="creating" kind="tool" @created="created" @cancel="creating = false" /></template>
